CREATE TABLE IF NOT EXISTS packets ("capture_id" VARCHAR,"frame" BIGINT,"ts" DOUBLE,"iface" INTEGER,"src" VARCHAR,"dst" VARCHAR,"sport" INTEGER,"dport" INTEGER,"proto" VARCHAR,"ipid" BIGINT,"seq" BIGINT,"ack" BIGINT,"flags" INTEGER,"length" INTEGER,"wirelen" INTEGER,"caplen" INTEGER,"prefix" VARCHAR,"payload_hash" VARCHAR,"signature" VARCHAR,"tuple_key" VARCHAR,"reverse_tuple" VARCHAR,"stream" BIGINT,"ttl" INTEGER,"dscp" INTEGER,"mss" INTEGER,"window" BIGINT,"retrans" BOOLEAN,"fast_retrans" BOOLEAN,"spurious" BOOLEAN,"out_of_order" BOOLEAN,"acked_unseen" BOOLEAN,"zero_window" BOOLEAN,"rtt" DOUBLE,"unsupported" VARCHAR,"frame_hash" VARCHAR,"icmp_id" INTEGER,"icmp_seq" INTEGER,"icmp_type" INTEGER,"dns_id" INTEGER,"dns_response" BOOLEAN,"vendor" VARCHAR,"path_fields" VARCHAR, PRIMARY KEY(capture_id, frame))